inputs.fragment_shader:
#version 300 es
precision highp float;

// ===============================================
// v2.0 - Skin Details Branch (Single Body Output)
// - One output only: body/base layer RGBA
// - Assumes downstream skin layer is plain white
// - Uses base color + base alpha to control visible tint amount
// - Adds detail texture input for transparency-only detail shaping
// ===============================================

uniform sampler2D u_image0;   // Original character image
uniform sampler2D u_image1;   // Skin mask (white = skin)
uniform sampler2D u_image2;   // Body mask (white = character body)
uniform sampler2D u_image3;   // Detail texture (grid/shadow lines) for alpha shaping only
uniform sampler2D u_image4;   // Optional mannequin body image (nude base)

uniform float u_float0;   // Contrast (default 1.4)
uniform float u_float1;   // Highlight Transparency Strength (default 0.7)
uniform float u_float2;   // Skin Layer Strength (default 1.5)
uniform float u_float3;   // Greyscale Curve Power (default 3.0)
uniform float u_float4;   // Body Mask Threshold (default 0.5) - higher = more aggressive
uniform float u_float5;   // High Zone Contrast (default 1.0)
uniform float u_float6;   // Line Trace Strength from detail texture (default 0.6)

uniform int u_int0;       // Skin Layer Min Alpha % (bright) - default 10 (= 0.10)
uniform int u_int1;       // Skin Layer Max Alpha % (dark)   - default 80 (= 0.80)
uniform int u_int2;       // Detail Texture Strength % (0-100, default 70 = 0.7)
uniform float u_float7;   // Line Trace Threshold (default 0.12)
uniform float u_float8;   // Base Gradient Tint Strength (default 0.45)

uniform float u_float9;   // Low Zone Alpha Multiplier (default 1.25)
uniform float u_float10;  // Mid Zone Alpha Multiplier (default 0.75)
uniform float u_float11;  // High Zone Alpha Multiplier (default 1.25)

uniform float u_float12;  // Low/Mid Split (default 0.33)
uniform float u_float13;  // Mid/High Split (default 0.66)
uniform float u_float14;  // Zone Blend Softness (default 0.12)

uniform float u_float15;  // Low Zone Brightness (default 0.0)
uniform float u_float16;  // Mid Zone Brightness (default 0.0)
uniform float u_float17;  // High Zone Brightness (default 0.0)

uniform float u_float18;  // Low Zone Contrast (default 1.0)
uniform float u_float19;  // Mid Zone Contrast (default 1.0)

uniform int u_int3;       // Preview Underlayer Color R (0-255, default 255)
uniform int u_int4;       // Preview Underlayer Color G (0-255, default 255)
uniform int u_int5;       // Preview Underlayer Color B (0-255, default 255)
uniform int u_int6;       // Reflective Extremes Opacity Boost % (0-200, default 35 = 0.35)
uniform int u_int7;       // Use mannequin input (0 = off, 1 = on)

in vec2 v_texCoord;

layout(location = 0) out vec4 fragColor0;  // Single Body/Base Output
layout(location = 1) out vec4 fragColor1;  // Unity-Style Preview
layout(location = 2) out vec4 fragColor2;  // Mannequin-Only Body Output (optional)
layout(location = 3) out vec4 fragColor3;  // Assembled Mannequin + Original Clothes (optional)

float sample_detail_luma(vec2 uv) {
    vec3 d = texture(u_image3, uv).rgb;
    return dot(d, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec4 original = texture(u_image0, v_texCoord);
    vec4 mannequin = texture(u_image4, v_texCoord);
    float skinMask = texture(u_image1, v_texCoord).r;
    float bodyMaskRaw = texture(u_image2, v_texCoord).r; // white on character body
    float detailLum = sample_detail_luma(v_texCoord);

    // Threshold body mask to binary (remove gray artifacts).
    // This keeps background transparent outside the body mask.
    float bodyMask = step(u_float4, bodyMaskRaw);

    if (bodyMask < 0.01) {
        fragColor0 = vec4(0.0);
        fragColor1 = vec4(0.0);
        fragColor2 = vec4(0.0);
        fragColor3 = vec4(0.0);
        return;
    }

    float lum = dot(original.rgb, vec3(0.299, 0.587, 0.114));
    float contrast = u_float0; // u_float0: expands/compresses luminance separation before grayscale shaping
    const float mid = 0.48;
    float boosted = (lum - mid) * contrast + mid;
    boosted = boosted / (boosted + 0.18);
    boosted = clamp(boosted, 0.0, 1.0);

    // Gradient used as tint guide for the base/body layer.
    vec3 skinGradient = vec3(pow(boosted, u_float3)); // u_float3: power curve controlling gradient rolloff

    // Build low/mid/high luminance zones with smooth blending.
    float splitLM = clamp(u_float12, 0.05, 0.95);
    float splitMH = clamp(u_float13, splitLM + 0.05, 0.98);
    float zoneSoft = max(clamp(u_float14, 0.0, 0.5), 0.0001);

    float low_w = 1.0 - smoothstep(splitLM - zoneSoft, splitLM + zoneSoft, boosted);
    float high_w = smoothstep(splitMH - zoneSoft, splitMH + zoneSoft, boosted);
    float mid_w = clamp(1.0 - low_w - high_w, 0.0, 1.0);

    float wsum = max(low_w + mid_w + high_w, 0.0001);
    low_w /= wsum;
    mid_w /= wsum;
    high_w /= wsum;

    // Base alpha control for white-underlayer workflow:
    // lower alpha => more of underlying plain-white skin layer shows through.
    float base_alpha_in_skin = 0.8 - (boosted * u_float1);

    // u_int0/u_int1 bounds and u_float2 strength shape transparency range in skin zones.
    // Flipped interpolation: dark zones (low boosted) lean toward max alpha, bright zones toward min alpha.
    float alpha_range = mix(float(u_int1) / 100.0, float(u_int0) / 100.0, boosted) * u_float2;
    base_alpha_in_skin *= alpha_range;

    // Per-zone transparency control (low/mid/high).
    float zone_alpha_mult =
        low_w * clamp(u_float9, 0.0, 3.0) +
        mid_w * clamp(u_float10, 0.0, 3.0) +
        high_w * clamp(u_float11, 0.0, 3.0);
    base_alpha_in_skin *= zone_alpha_mult;

    // Detail texture affects transparency only (grid/shadow details).
    // Darker detail texels reduce alpha more when strength increases.
    float detail_strength = clamp(float(u_int2) / 100.0, 0.0, 1.0);
    // Keep detail influence from collapsing alpha to near-zero in dark texels.
    float detail_alpha_factor = mix(1.0, mix(0.45, 1.0, clamp(detailLum, 0.0, 1.0)), detail_strength);

    // Optional line recognition/tracing from detail texture using local gradient magnitude.
    // This boosts transparency detail at detected line edges.
    ivec2 detailSize = textureSize(u_image3, 0);
    vec2 texel = vec2(1.0 / float(max(detailSize.x, 1)), 1.0 / float(max(detailSize.y, 1)));
    float dl = sample_detail_luma(v_texCoord + vec2(-texel.x, 0.0));
    float dr = sample_detail_luma(v_texCoord + vec2(texel.x, 0.0));
    float du = sample_detail_luma(v_texCoord + vec2(0.0, texel.y));
    float dd = sample_detail_luma(v_texCoord + vec2(0.0, -texel.y));
    float line_grad = length(vec2(dr - dl, du - dd));

    float line_threshold = clamp(u_float7, 0.0, 1.0);
    float line_mask = smoothstep(line_threshold, line_threshold + 0.15, line_grad);
    float line_strength = clamp(u_float6, 0.0, 1.0);
    // Make line trace shape alpha without fully flattening layer density.
    float line_alpha_factor = mix(1.0, 1.0 - (line_mask * 0.55), line_strength);

    float shaped_skin_alpha = clamp(base_alpha_in_skin * detail_alpha_factor * line_alpha_factor, 0.0, 1.0);

    // Reflective-style extremes behavior: apply after detail shaping so highlights can be recovered.
    float extreme_w = clamp(low_w + high_w, 0.0, 1.0);
    shaped_skin_alpha *= 1.0 + clamp(float(u_int6) / 100.0, 0.0, 2.0) * extreme_w;
    shaped_skin_alpha = clamp(shaped_skin_alpha, 0.0, 1.0);

    float base_alpha = mix(bodyMask, shaped_skin_alpha, skinMask) * bodyMask;

    // Base/body color gradient controls tint character in visible skin regions.
    // This is intentionally decoupled from alpha so we can keep stronger visual definition.
    float zone_contrast =
        low_w * clamp(u_float18, 0.0, 3.0) +
        mid_w * clamp(u_float19, 0.0, 3.0) +
        high_w * clamp(u_float5, 0.0, 3.0);
    float zone_brightness =
        low_w * clamp(u_float15, -1.0, 1.0) +
        mid_w * clamp(u_float16, -1.0, 1.0) +
        high_w * clamp(u_float17, -1.0, 1.0);

    vec3 zonedGradient = ((skinGradient - 0.5) * zone_contrast) + 0.5 + zone_brightness;
    zonedGradient = clamp(zonedGradient, 0.0, 1.0);

    float tint_strength = clamp(u_float8, 0.0, 1.0);
    vec3 skin_tinted_rgb = mix(original.rgb, zonedGradient, tint_strength);
    vec3 base_rgb = mix(original.rgb, skin_tinted_rgb, skinMask) * bodyMask;

    if (bodyMask < 0.01) {
        base_rgb = vec3(0.0);
        base_alpha = 0.0;
    }

    fragColor0 = vec4(clamp(base_rgb, 0.0, 1.0), clamp(base_alpha, 0.0, 1.0));

    // Unity preview for this branch:
    // - Top layer: base/body output (premultiplied by base_alpha)
    // - Under layer: white or custom test color revealed by transparency in skin regions
    vec3 custom_preview_color = vec3(
        clamp(float(u_int3), 0.0, 255.0),
        clamp(float(u_int4), 0.0, 255.0),
        clamp(float(u_int5), 0.0, 255.0)
    ) / 255.0;
    vec3 preview_under_color = custom_preview_color;

    float skin_under_alpha = clamp((1.0 - base_alpha) * skinMask * bodyMask, 0.0, 1.0);
    vec3 preview_rgb = clamp(base_rgb * base_alpha + preview_under_color * skin_under_alpha, 0.0, 1.0);
    fragColor1 = vec4(preview_rgb, 1.0);

    // Optional mannequin pipeline: recomputed entirely from mannequin's own luminance.
    // This ensures NO original image influence (no clothes bleed) in mannequin-only output.
    float use_mannequin = float(u_int7 > 0);
    float clothesMask = clamp((1.0 - skinMask) * bodyMask, 0.0, 1.0);

    // Mannequin luminance chain — mirrors base chain but driven by mannequin.rgb.
    float mq_lum = dot(mannequin.rgb, vec3(0.299, 0.587, 0.114));
    float mq_boosted = (mq_lum - mid) * contrast + mid;
    mq_boosted = mq_boosted / (mq_boosted + 0.18);
    mq_boosted = clamp(mq_boosted, 0.0, 1.0);

    vec3 mq_skinGradient = vec3(pow(mq_boosted, u_float3));

    float mq_low_w  = 1.0 - smoothstep(splitLM - zoneSoft, splitLM + zoneSoft, mq_boosted);
    float mq_high_w = smoothstep(splitMH - zoneSoft, splitMH + zoneSoft, mq_boosted);
    float mq_mid_w  = clamp(1.0 - mq_low_w - mq_high_w, 0.0, 1.0);
    float mq_wsum   = max(mq_low_w + mq_mid_w + mq_high_w, 0.0001);
    mq_low_w  /= mq_wsum;
    mq_mid_w  /= mq_wsum;
    mq_high_w /= mq_wsum;

    float mq_base_alpha = 0.8 - (mq_boosted * u_float1);
    float mq_alpha_range = mix(float(u_int1) / 100.0, float(u_int0) / 100.0, mq_boosted) * u_float2;
    mq_base_alpha *= mq_alpha_range;
    float mq_zone_alpha_mult =
        mq_low_w  * clamp(u_float9,  0.0, 3.0) +
        mq_mid_w  * clamp(u_float10, 0.0, 3.0) +
        mq_high_w * clamp(u_float11, 0.0, 3.0);
    mq_base_alpha *= mq_zone_alpha_mult;
    mq_base_alpha *= detail_alpha_factor * line_alpha_factor;

    float mq_shaped_alpha = clamp(mq_base_alpha, 0.0, 1.0);
    float mq_extreme_w = clamp(mq_low_w + mq_high_w, 0.0, 1.0);
    mq_shaped_alpha *= 1.0 + clamp(float(u_int6) / 100.0, 0.0, 2.0) * mq_extreme_w;
    mq_shaped_alpha = clamp(mq_shaped_alpha, 0.0, 1.0);

    float mq_zone_contrast =
        mq_low_w  * clamp(u_float18, 0.0, 3.0) +
        mq_mid_w  * clamp(u_float19, 0.0, 3.0) +
        mq_high_w * clamp(u_float5,  0.0, 3.0);
    float mq_zone_brightness =
        mq_low_w  * clamp(u_float15, -1.0, 1.0) +
        mq_mid_w  * clamp(u_float16, -1.0, 1.0) +
        mq_high_w * clamp(u_float17, -1.0, 1.0);
    vec3 mq_zonedGradient = clamp(((mq_skinGradient - 0.5) * mq_zone_contrast) + 0.5 + mq_zone_brightness, 0.0, 1.0);

    // Mannequin-only: pure mannequin body, tinted by its own luminance gradient. No original.rgb.
    vec3 mannequin_only_rgb   = mix(mannequin.rgb, mq_zonedGradient, tint_strength) * bodyMask;
    float mannequin_only_alpha = mq_shaped_alpha * bodyMask;

    // Assemble: mannequin skin zones tinted by original luminance, clothes from original.
    vec3 mq_skin_tinted = mix(mannequin.rgb, zonedGradient, tint_strength);
    vec3 assembled_rgb =
        (mq_skin_tinted * skinMask) +
        (original.rgb * clothesMask);
    float assembled_alpha = clamp((mq_shaped_alpha * skinMask) + clothesMask, 0.0, 1.0);

    fragColor2 = vec4(clamp(mannequin_only_rgb, 0.0, 1.0), clamp(mannequin_only_alpha, 0.0, 1.0)) * use_mannequin;
    fragColor3 = vec4(clamp(assembled_rgb, 0.0, 1.0), clamp(assembled_alpha, 0.0, 1.0)) * use_mannequin;
}
